<main class="content"><div class="catalog-grid"><?php foreach([['roles','Roles de usuario',$roles],['subjects','Asignaturas',$subjects],['tabulator_groups','Grupos de tabuladores',$groups],['tabulator_subgroups','Subgrupos de tabuladores',$subgroups]] as [$type,$label,$items]):?><section class="panel catalog-panel"><div class="panel-head"><div><span class="eyebrow">CONFIGURACIÓN</span><h2><?=e($label)?></h2></div><a class="primary compact" href="<?=url('/admin/catalogos/formulario?type='.$type)?>">+ Agregar</a></div><?php if(!$items):?><div class="empty">Sin registros.</div><?php else:?><ul class="clean-list"><?php foreach($items as $i):?><li><div><b>#<?=$i['id']?></b><span><?=e($i['name'])?></span></div><div class="action-row"><a class="view" href="<?=url('/admin/catalogos/formulario?type='.$type.'&id='.$i['id'].'&mode=view')?>">Ver</a><a class="edit" href="<?=url('/admin/catalogos/formulario?type='.$type.'&id='.$i['id'])?>">Editar</a><form method="post" action="<?=url('/admin/catalogos/eliminar')?>" onsubmit="return confirm('¿Eliminar este registro?')"><?=csrf_field()?><input type="hidden" name="type" value="<?=$type?>"><input type="hidden" name="id" value="<?=$i['id']?>"><button class="danger">Eliminar</button></form></div></li><?php endforeach;?></ul><?php endif;?></section><?php endforeach;?></div></main>
